import type { Context } from 'hono';
import type { AppEnvironment } from '@/app';
import type { SitePackageRevisionRecord } from '@/ports/repositories';
import {
    mainSiteOrigin,
    manifestEntries,
    requestedPackageAssetPath,
    sitePackageContentCsp,
    sitePackageFrameAncestorOrigins,
    sitePackageSlug,
    sitePackageUuid
} from '@/domains/site-packages/site-package-support';
import { sitePackageRepository, services } from '@/middleware/hono-context';
import { optimizeSitePackageContent } from '@/domains/site-packages/site-package-content';
import { storedObjectResponse } from '@/utils/http/stored-object-response';
import { sha256Hex } from '@/utils/crypto/sha256';

function publicPackageRevision(sitePackage: {
    id: string;
    published_revision_id: string | null;
}, revision: SitePackageRevisionRecord | null): SitePackageRevisionRecord | null {
    return revision !== null &&
        revision.published_at !== null &&
        revision.package_id === sitePackage.id &&
        revision.id === sitePackage.published_revision_id
        ? revision
        : null;
}

export async function handleGetPublicSitePackage(
    c: Context<AppEnvironment>
): Promise<Response> {
    let slug: string;
    try {
        slug = sitePackageSlug(c.req.param('slug'));
    } catch {
        return c.json({ error: '站点包不存在' }, 404);
    }
    const sitePackage = await sitePackageRepository(c).findSitePackageBySlug(slug);
    if (!sitePackage?.published_revision_id) return c.json({ error: '站点包不存在' }, 404);
    const revision = publicPackageRevision(
        sitePackage,
        await sitePackageRepository(c).findSitePackageRevisionById(
            sitePackage.id,
            sitePackage.published_revision_id
        )
    );
    if (!revision) return c.json({ error: '站点包不存在' }, 404);
    return c.json({
        slug: sitePackage.slug,
        title: sitePackage.title,
        description: sitePackage.description,
        revisionId: revision.id,
        revisionNumber: revision.revision_number,
        runtimeMode: revision.runtime_mode,
        publishedAt: revision.published_at,
        siteUrl: `${mainSiteOrigin(c)}/sites/${sitePackage.slug}`,
        contentUrl: `${mainSiteOrigin(c)}/site-content/${sitePackage.slug}/${revision.id}/`
    });
}

function escapeHtml(value: string): string {
    return value
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
}

function sitePackageShellCsp(contentOrigin: string): string {
    return [
        "default-src 'none'",
        "base-uri 'none'",
        "connect-src 'none'",
        `frame-src ${contentOrigin}`,
        "frame-ancestors 'none'",
        "form-action 'none'",
        "img-src 'none'",
        "object-src 'none'",
        "script-src 'none'",
        "style-src 'unsafe-inline'"
    ].join('; ');
}

function sitePackageShell(title: string, contentUrl: string): string {
    const escapedTitle = escapeHtml(title);
    const escapedContentUrl = escapeHtml(contentUrl);
    return `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapedTitle} | IMSWeb</title>
  <style>
    :root { color-scheme: light dark; font-family: Geist, "Noto Sans SC", "PingFang SC", sans-serif; }
    * { box-sizing: border-box; letter-spacing: 0; }
    html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
    body { display: flex; flex-direction: column; color: CanvasText; background: Canvas; }
    header { z-index: 1; display: flex; min-height: 56px; align-items: center; gap: 16px; padding: 0 20px; border-bottom: 1px solid color-mix(in srgb, CanvasText 14%, Canvas); background: Canvas; }
    a { flex: none; color: LinkText; font-size: 14px; font-weight: 600; text-decoration: none; }
    a:hover { text-decoration: underline; text-underline-offset: 3px; }
    a:focus-visible { outline: 3px solid Highlight; outline-offset: 3px; }
    h1 { min-width: 0; margin: 0; overflow: hidden; font-size: 14px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
    iframe { min-height: 0; width: 100%; flex: 1; border: 0; background: Canvas; }
    @media (max-width: 520px) { header { min-height: 52px; padding: 0 16px; } }
  </style>
</head>
<body>
  <header><a href="/">返回 IMSWeb</a><h1>${escapedTitle}</h1></header>
  <iframe src="${escapedContentUrl}" title="${escapedTitle}" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe>
</body>
</html>`;
}

export async function handleServePublishedSitePackageShell(
    c: Context<AppEnvironment>
): Promise<Response> {
    let slug: string;
    try {
        slug = sitePackageSlug(c.req.param('slug'));
    } catch {
        return c.text('Not Found', 404);
    }
    const sitePackage = await sitePackageRepository(c).findSitePackageBySlug(slug);
    if (!sitePackage?.published_revision_id) return c.text('Not Found', 404);
    const revision = publicPackageRevision(
        sitePackage,
        await sitePackageRepository(c).findSitePackageRevisionById(
            sitePackage.id,
            sitePackage.published_revision_id
        )
    );
    if (!revision) return c.text('Not Found', 404);
    const contentOrigin = mainSiteOrigin(c);
    const contentUrl = `${contentOrigin}/site-content/${slug}/${revision.id}/`;
    c.header('Cache-Control', 'no-cache');
    c.header('Content-Security-Policy', sitePackageShellCsp(contentOrigin));
    c.header('Permissions-Policy',
        'camera=(), geolocation=(), microphone=(), payment=(), usb=()');
    c.header('Referrer-Policy', 'no-referrer');
    c.header('X-Frame-Options', 'DENY');
    return c.html(sitePackageShell(sitePackage.title, contentUrl));
}

async function serveRevisionAsset(
    c: Context<AppEnvironment>,
    revision: SitePackageRevisionRecord,
    slug: string,
    routeSegments: readonly string[],
    preview: boolean
): Promise<Response> {
    const runtime = services(c);
    if (!runtime.storage) throw new Error('Object storage unavailable');
    const assetPath = requestedPackageAssetPath(c.req.raw, routeSegments, revision.entry_path);
    if (!assetPath) return c.text('Not Found', 404);
    const objectKey = manifestEntries(revision).get(assetPath);
    const expectedKey = `site-packages/${revision.package_id}/revisions/` +
        `${revision.id}/files/${assetPath}`;
    if (!objectKey || objectKey !== expectedKey) return c.text('Not Found', 404);
    const stored = await runtime.storage.get(objectKey);
    if (!stored) return c.text('Not Found', 404);
    const object = await optimizeSitePackageContent(stored);
    const headers = new Headers({
        'Cache-Control': preview
            ? 'private, no-store'
            : /^text\/html(?:;|$)/i.test(object.contentType)
                ? 'public, max-age=0, must-revalidate'
                : 'public, max-age=31536000, immutable',
        'Content-Security-Policy': sitePackageContentCsp(
            revision.runtime_mode,
            sitePackageFrameAncestorOrigins(mainSiteOrigin(c))
        ),
        'Permissions-Policy':
            'camera=(), geolocation=(), microphone=(), payment=(), usb=()',
        'Referrer-Policy': 'no-referrer',
        'X-Site-Package': `${slug}:${revision.id}`
    });
    headers.delete('X-Frame-Options');
    return storedObjectResponse(c.req.raw, object, headers);
}

export async function handleServePublishedSitePackage(
    c: Context<AppEnvironment>
): Promise<Response> {
    let slug: string;
    let revisionId: string;
    try {
        slug = sitePackageSlug(c.req.param('slug'));
        revisionId = sitePackageUuid(c.req.param('revisionId'), '版本 ID');
    } catch {
        return c.text('Not Found', 404);
    }
    const sitePackage = await sitePackageRepository(c).findSitePackageBySlug(slug);
    if (!sitePackage) return c.text('Not Found', 404);
    const revision = publicPackageRevision(
        sitePackage,
        await sitePackageRepository(c).findSitePackageRevisionById(sitePackage.id, revisionId)
    );
    if (!revision) return c.text('Not Found', 404);
    return serveRevisionAsset(
        c,
        revision,
        slug,
        ['site-content', slug, revisionId],
        false
    );
}

export async function handleServePreviewSitePackage(
    c: Context<AppEnvironment>
): Promise<Response> {
    const previewToken = String(c.req.param('previewToken') || '');
    if (!/^[a-f0-9]{64}$/i.test(previewToken)) return c.text('Not Found', 404);
    const previewTokenHash = await sha256Hex(new TextEncoder().encode(previewToken));
    const revision = await sitePackageRepository(c).findSitePackageRevisionByPreviewTokenHash(
        previewTokenHash
    );
    if (!revision) return c.text('Not Found', 404);
    return serveRevisionAsset(
        c,
        revision,
        revision.slug,
        ['site-content', '_preview', previewToken],
        true
    );
}
